const update = $input.first().json;

let messageText, chatId, userId, username, messageId;

if (update.callback_query) {
  messageText = update.callback_query.data;
  chatId = update.callback_query.message.chat.id;
  userId = update.callback_query.from.id;
  username = update.callback_query.from.username || update.callback_query.from.first_name;
  messageId = update.callback_query.message.message_id;
} else {
  messageText = update.message?.text || '';
  chatId = update.message?.chat?.id;
  userId = update.message?.from?.id;
  username = update.message?.from?.username || update.message?.from?.first_name || 'User';
  messageId = update.message?.message_id;
}

if (!messageText) {
  return [{ json: { skip: true, reason: 'non_text_message' } }];
}

return [{
  json: {
    chat_id: chatId,
    user_id: userId,
    username: username,
    message_text: messageText,
    message_id: messageId,
    is_command: messageText.startsWith('/'),
    timestamp: new Date().toISOString()
  }
}];

const cmd = $input.first().json.message_text.split(' ')[0];
let response = '';

switch(cmd) {
  case '/start':
    response = '👋 Welcome! I am your AI Support Bot.\nAvailable commands:\n/help - Show this message\n/about - Learn what I can do\n\nJust type any question to get started!';
    break;
  case '/help':
    response = 'I can help you with:\n- Technical support questions\n- Product information\n- General inquiries\n- Troubleshooting\n\nJust send me your question and I will analyze it!';
    break;
  case '/about':
    response = 'I am an AI-powered support bot built on n8n.\nI use GPT-4o-mini to understand and respond to inquiries.\n\nBuilt with ❤️ using n8n + OpenAI.';
    break;
  default:
    response = 'Unknown command. Type /help to see available commands.';
}

return [{ json: { ...$input.first().json, ai_reply: response } }];

