const aiReply = $input.first().json.output || $input.first().json.text || 'Sorry, I could not process your request.';
const truncated = aiReply.length > 4000 ? aiReply.substring(0, 3997) + '...' : aiReply;

return [{
  json: {
    chat_id: $json.chat_id,
    text: truncated,
    parse_mode: 'Markdown',
    reply_to_message_id: $json.message_id,
    user_message: $json.message_text,
    response_tokens: Math.round(truncated.length / 4),
    processing_time_ms: 'real-time'
  }
}];
